1	//! Helpers for end-to-end tests and benches that run against the Stylus SDK
2	//! devnet.
3	//!
4	//! The devnet is provided by `stylus-tools` (a pinned Nitro node started in
5	//! Docker). Set `RPC_URL` to use a node that is already running; otherwise the
6	//! first call starts one for the current process.
7	
8	pub mod assert;
9	
10	use std::{
11	    path::{Path, PathBuf},
12	    sync::OnceLock,
13	};
14	
15	use alloy::{
16	    network::{EthereumWallet, TransactionBuilder},
17	    primitives::{Address, Bytes, B256, U256},
18	    providers::{Provider, ProviderBuilder},
19	    rpc::types::TransactionRequest,
20	    signers::local::PrivateKeySigner,
21	    sol_types::SolCall,
22	};
23	use stylus_tools::{
24	    core::{
25	        check::{check_wasm_file, CheckConfig},
26	        deployment::{
27	            deployer::{get_address_from_receipt, stylus_constructorCall, StylusDeployer},
28	            prelude::DeploymentCalldata,
29	            request::DeploymentRequest,
30	        },
31	    },
32	    devnet::{addresses::STYLUS_DEPLOYER, DEVNET_PRIVATE_KEY},
33	};
34	
35	/// Ether sent to each account created by [`funded_account`].
36	pub const DEFAULT_FUNDING_ETH: u64 = 10;
37	
38	static RPC_URL: OnceLock<String> = OnceLock::new();
39	
40	/// Serializes the funding transactions sent from the devnet owner key so that
41	/// their nonces do not collide when tests run in parallel.
42	static FUNDING: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());
43	
44	/// Returns the RPC URL of the devnet used by this process.
45	///
46	/// The first call starts a devnet in a background thread that lives until the
47	/// process exits, unless `RPC_URL` is set. The devnet container is removed by
48	/// Docker when the process exits.
49	///
50	/// # Panics
51	///
52	/// Panics if the devnet cannot be started (for example when Docker is not
53	/// running).
54	#[must_use]
55	pub fn rpc_url() -> &'static str {
56	    RPC_URL
57	        .get_or_init(|| {
58	            if let Ok(url) = std::env::var("RPC_URL") {
59	                return url;
60	            }
61	            let (sender, receiver) = std::sync::mpsc::channel();
62	            std::thread::spawn(move || {
63	                let runtime = tokio::runtime::Builder::new_multi_thread()
64	                    .enable_all()
65	                    .build()
66	                    .expect("failed to build the devnet runtime");
67	                runtime.block_on(async move {
68	                    let node = stylus_tools::devnet::Node::new()
69	                        .await
70	                        .expect("failed to start the devnet");
71	                    sender
72	                        .send(node.rpc().to_owned())
73	                        .expect("the test process is gone");
74	                    // Keep the node, and therefore its container, alive.
75	                    std::future::pending::<()>().await;
76	                });
77	            });
78	            receiver.recv().expect("the devnet did not start")
79	        })
80	        .as_str()
81	}
82	
83	/// An externally owned account on the devnet.
84	#[derive(Clone, Debug)]
85	pub struct Account {
86	    signer: PrivateKeySigner,
87	    rpc: &'static str,
88	}
89	
90	impl Account {
91	    /// Address of the account.
92	    #[must_use]
93	    pub fn address(&self) -> Address {
94	        self.signer.address()
95	    }
96	
97	    /// Creates a provider that signs transactions with this account.
98	    ///
99	    /// # Errors
100	    ///
101	    /// Returns an error if the RPC endpoint cannot be reached.
102	    pub async fn provider(
103	        &self,
104	    ) -> eyre::Result<impl Provider + Clone + 'static> {
105	        let wallet = EthereumWallet::from(self.signer.clone());
106	        Ok(ProviderBuilder::new().wallet(wallet).connect(self.rpc).await?)
107	    }
108	}
109	
110	/// Creates a new random account funded with [`DEFAULT_FUNDING_ETH`] ether
111	/// from the devnet owner.
112	///
113	/// # Errors
114	///
115	/// Returns an error if the funding transaction fails.
116	pub async fn funded_account() -> eyre::Result<Account> {
117	    fund(PrivateKeySigner::random(), DEFAULT_FUNDING_ETH).await
118	}
119	
120	/// Creates a new random account funded with `eth` ether from the devnet owner.
121	///
122	/// # Errors
123	///
124	/// Returns an error if the funding transaction fails.
125	pub async fn fund(signer: PrivateKeySigner, eth: u64) -> eyre::Result<Account> {
126	    let rpc = rpc_url();
127	    let account = Account { signer, rpc };
128	    let owner: PrivateKeySigner = DEVNET_PRIVATE_KEY.parse()?;
129	    let owner_provider = ProviderBuilder::new()
130	        .wallet(EthereumWallet::from(owner))
131	        .connect(rpc)
132	        .await?;
133	
134	    let _funding = FUNDING.lock().await;
135	    let value = U256::from(eth) * U256::from(10).pow(U256::from(18));
136	    let tx = TransactionRequest::default().with_to(account.address()).with_value(value);
137	    owner_provider.send_transaction(tx).await?.get_receipt().await?;
138	    Ok(account)
139	}
140	
141	/// Returns the path of the release `.wasm` built for a contract crate.
142	///
143	/// The name is the crate name, for example `erc20-example`. Build the files
144	/// first with `cargo build --release --target wasm32-unknown-unknown`.
145	#[must_use]
146	pub fn wasm_path(crate_name: &str) -> PathBuf {
147	    let target = std::env::var_os("CARGO_TARGET_DIR").map_or_else(
148	        || Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target"),
149	        PathBuf::from,
150	    );
151	    target
152	        .join("wasm32-unknown-unknown/release")
153	        .join(format!("{}.wasm", crate_name.replace('-', "_")))
154	}
155	
156	/// Deploys and activates a Stylus contract and returns its address.
157	///
158	/// `constructor_args` must be the ABI encoding of the constructor arguments,
159	/// for example `(name, symbol, cap).abi_encode_params()`, or `None` for a
160	/// contract without a constructor.
161	///
162	/// # Errors
163	///
164	/// Returns an error if the WASM cannot be checked, the contract is too large
165	/// for a single deployment, or the transaction fails.
166	pub async fn deploy(
167	    account: &Account,
168	    wasm: impl AsRef<Path>,
169	    constructor_args: Option<Bytes>,
170	) -> eyre::Result<Address> {
171	    let provider = account.provider().await?;
172	    let from = account.address();
173	
174	    let status = check_wasm_file(
175	        wasm,
176	        Default::default(),
177	        None,
178	        None,
179	        &CheckConfig::default(),
180	        &provider,
181	    )
182	    .await?;
183	    let fee = status.suggest_fee();
184	    let code = match status.code() {
185	        stylus_tools::core::code::Code::Contract(code) => code.0.clone(),
186	        stylus_tools::core::code::Code::Fragments(_) => {
187	            eyre::bail!("fragmented contracts are not supported by the devnet helper")
188	        }
189	    };
190	
191	    let receipt = match constructor_args {
192	        None => DeploymentRequest::new(from, &code, None).exec(&provider).await?,
193	        Some(args) => {
194	            let mut constructor = stylus_constructorCall::SELECTOR.to_vec();
195	            constructor.extend_from_slice(&args);
196	            let calldata = StylusDeployer::new(Address::ZERO, &provider)
197	                .deploy_call(
198	                    DeploymentCalldata::new(&code).into(),
199	                    constructor.into(),
200	                    U256::ZERO,
201	                    B256::ZERO,
202	                )
203	                .calldata()
204	                .to_vec();
205	            let receipt =
206	                DeploymentRequest::new_with_args(from, STYLUS_DEPLOYER, fee, calldata, None)
207	                    .exec(&provider)
208	                    .await?;
209	            return Ok(get_address_from_receipt(&receipt)?);
210	        }
211	    };
212	    receipt
213	        .contract_address
214	        .ok_or_else(|| eyre::eyre!("the deployment receipt has no contract address"))
215	}
216	
217

1	//! Assertions for end-to-end tests.
2	//!
3	//! The helpers keep the strength of the assertions the v0.3.0 end-to-end
4	//! framework made: a revert must carry the exact ABI encoding of the expected
5	//! error, an event must decode to the expected value, and a panic is a
6	//! generic execution revert.
7	
8	use alloy::{
9	    contract,
10	    primitives::Bytes,
11	    rpc::{json_rpc::RpcError, types::TransactionReceipt},
12	    sol_types::{SolError, SolEvent},
13	    transports::TransportErrorKind,
14	};
15	
16	/// Returns the revert data that the node reported for a failed call.
17	///
18	/// Returns `None` when the error is not a node response or the node reported
19	/// no data, which is how Stylus panics are reported.
20	#[must_use]
21	pub fn revert_data(error: &contract::Error) -> Option<Bytes> {
22	    let contract::Error::TransportError(error) = error else {
23	        return None;
24	    };
25	    revert_data_of_rpc(error)
26	}
27	
28	/// Returns whether a failed call reverted with exactly the ABI encoding of
29	/// `expected`.
30	#[must_use]
31	pub fn reverted_with<E: SolError>(error: &contract::Error, expected: &E) -> bool {
32	    revert_data(error).is_some_and(|data| data.as_ref() == expected.abi_encode())
33	}
34	
35	/// Returns whether a failed call is a generic execution revert, which the
36	/// node uses for Stylus panics.
37	#[must_use]
38	pub fn is_execution_revert(error: &contract::Error) -> bool {
39	    let contract::Error::TransportError(error) = error else {
40	        return false;
41	    };
42	    error.as_error_resp().is_some_and(|payload| {
43	        payload.code == -32000 && payload.message == "execution reverted"
44	    })
45	}
46	
47	/// Returns whether a deployment error, which carries the RPC error in its
48	/// chain, reverted with the ABI encoding of `expected`.
49	#[must_use]
50	pub fn deployment_reverted_with<E: SolError>(
51	    report: &eyre::Report,
52	    expected: &E,
53	) -> bool {
54	    let Some(error) = report
55	        .chain()
56	        .find_map(|cause| cause.downcast_ref::<RpcError<TransportErrorKind>>())
57	    else {
58	        return false;
59	    };
60	    revert_data_of_rpc(error)
61	        .is_some_and(|data| data.as_ref() == expected.abi_encode())
62	}
63	
64	/// Returns whether the receipt contains an event that decodes to `expected`.
65	#[must_use]
66	pub fn emits<E>(receipt: &TransactionReceipt, expected: &E) -> bool
67	where
68	    E: SolEvent + PartialEq,
69	{
70	    receipt
71	        .inner
72	        .logs()
73	        .iter()
74	        .filter_map(|log| log.log_decode::<E>().ok())
75	        .any(|decoded| &decoded.inner.data == expected)
76	}
77	
78	fn revert_data_of_rpc(error: &RpcError<TransportErrorKind>) -> Option<Bytes> {
79	    let payload = error.as_error_resp()?;
80	    let raw = payload.data.as_ref()?;
81	    let hex = raw.get().trim_matches('"');
82	    alloy::hex::decode(hex).ok().map(Bytes::from)
83	}
84

