/// This macro provides a shorthand for broadcasting the transaction to the
/// network.
///
/// See: <https://docs.rs/alloy-contract/0.8.3/alloy_contract/struct.CallBuilder.html>
///
/// # Examples
///
/// ```rust,ignore
/// #[e2e::test]
/// async fn foo(alice: Account) -> eyre::Result<()> {
///     let contract_addr = alice.as_deployer().deploy().await?.contract_address;
///     let contract = Erc721::new(contract_addr, &alice.wallet);
///
///     let alice_addr = alice.address();
///     let token_id = random_token_id();
///     let pending_tx = send!(contract.mint(alice_addr, token_id))?;
///     // ...
/// }
#[macro_export]
macro_rules! send {
    ($e:expr) => {
        $e.send().await
    };
}

/// This macro provides a shorthand for broadcasting the transaction
/// to the network, and then waiting for the given number of confirmations.
///
/// See: <https://docs.rs/alloy-provider/0.8.3/alloy_provider/struct.PendingTransactionBuilder.html>
///
/// # Examples
///
/// ```rust,ignore
/// #[e2e::test]
/// async fn foo(alice: Account) -> eyre::Result<()> {
///     let contract_addr = alice.as_deployer().deploy().await?.contract_address;
///     let contract = Erc721::new(contract_addr, &alice.wallet);
///
///     let alice_addr = alice.address();
///     let token_id = random_token_id();
///     let result = watch!(contract.mint(alice_addr, token_id))?;
///     // ...
/// }
#[macro_export]
macro_rules! watch {
    ($e:expr) => {
        $crate::send!($e)?.watch().await
    };
}

/// This macro provides a shorthand for broadcasting the transaction
/// to the network, waiting for the given number of confirmations, and then
/// fetching the transaction receipt.
///
/// See: <https://docs.rs/alloy-provider/0.8.3/alloy_provider/struct.PendingTransactionBuilder.html>
///
/// # Examples
///
/// ```rust,ignore
/// #[e2e::test]
/// async fn foo(alice: Account) -> eyre::Result<()> {
///     let contract_addr = alice.as_deployer().deploy().await?.contract_address;
///     let contract = Erc721::new(contract_addr, &alice.wallet);
///
///     let alice_addr = alice.address();
///     let token_id = random_token_id();
///     let receipt = receipt!(contract.mint(alice_addr, token_id))?;
///     // ...
/// }
#[macro_export]
macro_rules! receipt {
    ($e:expr) => {
        $crate::send!($e)?.get_receipt().await
    };
}
use alloy::{
    sol_types::SolError,
    transports::{RpcError, TransportErrorKind},
};
use stylus_sdk::call::MethodError;

/// Possible panic codes for a revert.
///
/// Taken from <https://github.com/NomicFoundation/hardhat/blob/main/packages/hardhat-chai-matchers/src/internal/reverted/panic.ts>
#[derive(Debug)]
#[allow(missing_docs)] // Pretty straightforward variant names.
pub enum PanicCode {
    AssertionError = 0x1,
    ArithmeticOverflow = 0x11,
    DivisionByZero = 0x12,
    EnumConversionOutOfBounds = 0x21,
    IncorrectlyEncodedStorageByteArray = 0x22,
    PopOnEmptyArray = 0x31,
    ArrayAccessOutOfBounds = 0x32,
    TooMuchMemoryAllocated = 0x41,
    ZeroInitializedVariable = 0x51,
}

impl core::fmt::Display for PanicCode {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let msg = match self {
            PanicCode::AssertionError =>
                "Assertion error",
            PanicCode::ArithmeticOverflow =>
                "Arithmetic operation overflowed outside of an unchecked block",
            PanicCode::DivisionByZero =>
                "Division or modulo division by zero",
            PanicCode::EnumConversionOutOfBounds =>
                "Tried to convert a value into an enum, but the value was too big or negative",
            PanicCode::IncorrectlyEncodedStorageByteArray =>
                "Incorrectly encoded storage byte array",
            PanicCode::PopOnEmptyArray =>
                ".pop() was called on an empty array",
            PanicCode::ArrayAccessOutOfBounds =>
                "Array accessed at an out-of-bounds or negative index",
