        let raw_value = e
            .as_error_resp()
            .and_then(|payload| payload.data.clone())
            .expect("should extract the error");

        let actual = &raw_value.get().trim_matches('"')[2..];
        let expected = alloy::hex::encode(expected.encode());
        expected == actual
    }
}

