                    .map_err(|e: RpcError<TransportErrorKind>| {
                        eyre::eyre!("RPC error: {}", e)
                    })?
                    .ok_or_else(|| {
                        eyre::eyre!("Transaction receipt not found")
                    })?;

                let input = tx.input().encode_hex();

                // The pattern matches the contract address contained in the
                // input
